// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // Fuzz parameters: actor (the recipient) and deposit amount
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep actor non-zero and amount within reasonable bound so vm.deal works
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy a recorder that can optionally revert when receiving funds.
        Recorder rec = new Recorder();

        // Fund the actor so they can be used as msg.sender by vm.prank if needed
        vm.deal(address(this), 2 ether);

        // Deposit into c on behalf of the recorder address (we need recorder to be credited)
        // We impersonate the recorder to make the deposit credited to its address
        vm.deal(address(rec), amount);
        vm.prank(address(rec));
        // call deposit sending `amount` to c
        c.deposit{value: amount}();

        // At this point, reference C guarantees that a withdrawAll by the credited address
        // will attempt to send `amount` to that address and then set its credit to 0 and reduce c.balance.
        // To observe the external call, we make the recorder be the recipient (it is the credited address),
        // and we configure the recorder to record calls and not revert for this run.
        rec.setShouldRevert(false);

        // Now perform withdrawAll as the recorder (prank as rec address)
        vm.prank(address(rec));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (observed via c and the recorder): for nonzero credit, the call completes
        // successfully and the recorder observed receiving `amount` and c.balance decreased by amount.
        // We assert this property which holds for the reference C for all admissible inputs,
        // but the mutant (which inverts the guard) will attempt the send when credit == 0 and can
        // behave differently for some inputs (e.g., if recorder set to revert). Here we assert the
        // success path for the nonzero credit case.

        // recorder should have recorded exactly one incoming call with value == amount
        assertTrue(ok);
        assertTrue(rec.callCount() == 1);
        assertTrue(rec.lastValue() == amount);
        // c.balance should be zero now (since we deposited amount then withdrew it)
        assertTrue(address(c).balance == 0);
        // And the recorder's recorded observed credited flag is true (it recorded the call from c)
        assertTrue(rec.lastSender() == address(c));
    }
}

// Recorder that records incoming calls and can be set to revert
contract Recorder {
    uint public callCount;
    uint public lastValue;
    address public lastSender;
    bool public shouldRevert;

    function setShouldRevert(bool r) external {
        shouldRevert = r;
    }

    receive() external payable {
        callCount += 1;
        lastValue = msg.value;
        lastSender = msg.sender;
        if (shouldRevert) revert("rec revert");
    }

    fallback() external payable {
        callCount += 1;
        lastValue = msg.value;
        lastSender = msg.sender;
        if (shouldRevert) revert("rec revert");
    }
}
